/-! Strict improvements in both cubic inverse parameters, for every alpha in (0,1].
These comparisons concern the proved discrepancy and average-size parameters;
no comparison of the full five-term starting thresholds is inferred. -/

def cubicDiscrepancyExponent (alpha : Real) : Real :=
  cubicLocalizationExponent alpha * cubicLocalCountExponent alpha /
    (2 * (polynomialPartitionConstant 3 : Real))

def cubicPhaseRefinementConstant (alpha : Real) : Real :=
  section5LocalRefinementConstant 3 (cubicTwistedDiscrepancyParameter alpha) *
    (cubicTwistedCountConstant alpha) ^ (polynomialPartitionConstant 3 : Real)⁻¹

def cubicTwistedThreshold (alpha : Real) : Real :=
  cubicPrimeModelThreshold alpha
    (max 4 (quadraticExponentialThreshold (cubicLocalQuadraticParameter alpha)))

def fejerCubicDiscrepancyExponent (alpha : Real) : Real :=
  fejerCubicLocalizationExponent alpha * fejerCubicLocalCountExponent alpha /
    (2 * (polynomialPartitionConstant 3 : Real))

def fejerCubicPhaseRefinementConstant (alpha : Real) : Real :=
  section5LocalRefinementConstant 3 (fejerCubicTwistedDiscrepancyParameter alpha) *
    (fejerCubicTwistedCountConstant alpha) ^ (polynomialPartitionConstant 3 : Real)⁻¹

def fejerCubicTwistedThreshold (alpha : Real) : Real :=
  fejerCubicPrimeModelThreshold alpha
    (max 4 (quadraticExponentialThreshold (fejerCubicLocalQuadraticParameter alpha)))

def intervalDiscrepancyClosedThreshold (k : Nat) (delta beta sigma T : Real) : Real :=
  densityIterationClosedThreshold (intervalDiscrepancyStepThreshold k delta beta T)
    (beta / (8 * boundaryRefinementConstant (beta / 64))) (sigma / 16) ⌈(beta / 8)⁻¹⌉₊

def quadraticExponentialThreshold (alpha : Real) : Real :=
  Real.exp ((4 + 6 * section5LocalRefinementConstant 2 1) *
    (2 / alpha) ^ (12380 * 2048 + 24744 : Nat))

def section13FejerOddSquareThreshold (alpha : Real) : Real :=
  max (section13FourierThreshold alpha)
    (positivePowerThreshold 4 1 ((1 / 2 : Real) ^ ((2 / alpha) ^ ((2 : Nat) ^ 53))))

def section13FourierThreshold (alpha : Real) : Real :=
  max (section13FrequencyGraphThreshold alpha)
    (section13GeometricThreshold ((alpha / 2) ^ (4207554485 : Nat)))

def section13OddSquareThreshold (alpha : Real) : Real :=
  max (section13FourierThreshold alpha)
    (positivePowerThreshold 4 1 ((1 / 2 : Real) ^ ((2 / alpha) ^ ((2 : Nat) ^ 88))))
